export const designSystemTokenCss = "/* ============================================================\n   RepoAssure — Color primitives (scales) + semantic tokens.\n   Architecture (Primer-inspired):\n     1. Primitive scales  — raw hues, never used by components.\n     2. Semantic tokens   — theme-aware, the ONLY layer components read.\n   Themes: default (light) on :root, dark via [data-theme=\"dark\"].\n   Console tokens are theme-independent (the always-dark instrument surface).\n   ============================================================ */\n:root{\n  /* -- Neutral: cool navy-tinted ink ramp -------------------- */\n  --ink-0:#f6f8fb; --ink-1:#eef2f7; --ink-2:#e1e8f0; --ink-3:#cbd6e2;\n  --ink-4:#a7b7c9; --ink-5:#8091a7; --ink-6:#5f7089; --ink-7:#47566b;\n  --ink-8:#334255; --ink-9:#212f42; --ink-10:#14202f; --ink-11:#0c1725; --ink-12:#050d18;\n\n  /* -- Assurance green (primary accent) ---------------------- */\n  --green-0:#e6f9ef; --green-1:#c1f0d6; --green-2:#8ce4b6; --green-3:#52d290;\n  --green-4:#22c06f; --green-5:#06a85c; --green-6:#018a4c; --green-7:#036e3e;\n  --green-8:#0a5733; --green-9:#0b3f27;\n\n  /* -- Control blue (informational) -------------------------- */\n  --blue-0:#eaf1ff; --blue-1:#cfe0ff; --blue-2:#a6c6ff; --blue-3:#7aa5ff;\n  --blue-4:#5286ff; --blue-5:#356bf0; --blue-6:#2653cf; --blue-7:#1d40a3;\n  --blue-8:#1a3379; --blue-9:#152551;\n\n  /* -- Red (P0 / danger) ------------------------------------- */\n  --red-0:#fdecec; --red-1:#fbcfcf; --red-2:#f5a3a3; --red-3:#ec7373;\n  --red-4:#e04848; --red-5:#cf2f2f; --red-6:#ad2020; --red-7:#871b1b;\n  --red-8:#661818; --red-9:#481414;\n\n  /* -- Amber (P1 / warning) ---------------------------------- */\n  --amber-0:#fdf1dd; --amber-1:#fbe0b3; --amber-2:#f7c877; --amber-3:#f0ab3a;\n  --amber-4:#e0900f; --amber-5:#c2790a; --amber-6:#9c6008; --amber-7:#7a4b0a;\n  --amber-8:#5c390b; --amber-9:#422a0b;\n\n  /* -- Violet (integrity / content-hash accent) --------------- */\n  --violet-0:#f0ecfe; --violet-1:#ddd3fc; --violet-2:#c1adf8; --violet-3:#a184f2;\n  --violet-4:#8460e8; --violet-5:#6d47d6; --violet-6:#5836b5; --violet-7:#452a8f;\n  --violet-8:#35226c; --violet-9:#271a4d;\n\n  /* -- Console (always-dark instrument surface, theme-agnostic) */\n  --console-bg:#0a1420;\n  --console-bg-chrome:#061019;\n  --console-surface:#101f31;\n  --console-fg:#e7edf5;\n  --console-fg-muted:#8698ad;\n  --console-border:rgba(148,163,184,.16);\n}\n\n/* ================= LIGHT (default) ========================= */\n:root,[data-theme=\"light\"]{\n  color-scheme:light;\n  --fg-default:var(--ink-11);\n  --fg-muted:var(--ink-7);\n  --fg-subtle:var(--ink-6);\n  --fg-on-emphasis:#ffffff;\n\n  --canvas-default:#ffffff;\n  --canvas-subtle:var(--ink-0);\n  --canvas-inset:var(--ink-1);\n  --surface-default:#ffffff;\n  --surface-raised:#ffffff;\n  --surface-overlay:#ffffff;\n\n  --border-default:var(--ink-2);\n  --border-muted:var(--ink-1);\n  --border-strong:var(--ink-3);\n\n  /* --accent-fg is the text-grade accent. green-6 (#018a4c) reaches only 4.43:1 on the\n     light canvas, which fails AA for the 12px eyebrow and 13px chip labels that use it;\n     green-7 reaches 5.82:1. --accent-emphasis keeps green-5 for fills and strokes, where\n     no contrast minimum applies. */\n  --accent-fg:var(--green-7);\n  --accent-emphasis:var(--green-5);\n  /* The one accent fill that carries white text. green-5 under #fff is 3.10:1, so a\n     primary button fails AA at every size the system offers (14-16px, weight 600 — never\n     large text). Kept separate from --accent-emphasis so the brand mark, checkbox fill,\n     and tab underline keep the vivid green, where no contrast minimum applies. */\n  --accent-emphasis-strong:var(--green-7);\n  --accent-muted:var(--green-2);\n  --accent-subtle:var(--green-0);\n\n  --link-fg:var(--blue-5);\n  --link-hover-fg:var(--blue-6);\n\n  --info-fg:var(--blue-6);    --info-emphasis:var(--blue-5);  --info-muted:var(--blue-2);   --info-subtle:var(--blue-0);\n  --success-fg:var(--green-6);--success-emphasis:var(--green-5);--success-muted:var(--green-2);--success-subtle:var(--green-0);\n  --danger-fg:var(--red-6);   --danger-emphasis:var(--red-5); --danger-muted:var(--red-2);  --danger-subtle:var(--red-0);\n  --warning-fg:var(--amber-6);--warning-emphasis:var(--amber-4);--warning-muted:var(--amber-2);--warning-subtle:var(--amber-0);\n  --verified-fg:var(--violet-6);--verified-emphasis:var(--violet-5);--verified-muted:var(--violet-2);--verified-subtle:var(--violet-0);\n\n  /* severity aliases (P0/P1/P2) */\n  --sev-p0-fg:var(--danger-fg); --sev-p0-subtle:var(--danger-subtle); --sev-p0-muted:var(--danger-muted);\n  --sev-p1-fg:var(--warning-fg);--sev-p1-subtle:var(--warning-subtle);--sev-p1-muted:var(--warning-muted);\n  --sev-p2-fg:var(--info-fg);   --sev-p2-subtle:var(--info-subtle);   --sev-p2-muted:var(--info-muted);\n\n  --focus-ring:var(--blue-4);\n}\n\n/* ================= DARK ==================================== */\n[data-theme=\"dark\"]{\n  color-scheme:dark;\n  --fg-default:var(--ink-0);\n  --fg-muted:var(--ink-4);\n  --fg-subtle:var(--ink-5);\n  --fg-on-emphasis:#ffffff;\n\n  --canvas-default:var(--ink-12);\n  --canvas-subtle:var(--ink-11);\n  --canvas-inset:#04101d;\n  --surface-default:var(--ink-10);\n  --surface-raised:var(--ink-9);\n  --surface-overlay:var(--ink-9);\n\n  --border-default:rgba(148,163,184,.18);\n  --border-muted:rgba(148,163,184,.10);\n  --border-strong:rgba(148,163,184,.30);\n\n  --accent-fg:var(--green-3);\n  --accent-emphasis:var(--green-5);\n  /* Same reason as light: the primary button's white label needs a darker fill than the\n     brand green to clear AA. */\n  --accent-emphasis-strong:var(--green-7);\n  --accent-muted:rgba(6,168,92,.42);\n  --accent-subtle:rgba(6,168,92,.14);\n\n  --link-fg:var(--blue-3);\n  --link-hover-fg:var(--blue-2);\n\n  --info-fg:var(--blue-3);    --info-emphasis:var(--blue-5);  --info-muted:rgba(82,134,255,.42);   --info-subtle:rgba(82,134,255,.14);\n  --success-fg:var(--green-3);--success-emphasis:var(--green-5);--success-muted:rgba(6,168,92,.42);--success-subtle:rgba(6,168,92,.14);\n  --danger-fg:var(--red-3);   --danger-emphasis:var(--red-5); --danger-muted:rgba(224,72,72,.42);  --danger-subtle:rgba(224,72,72,.14);\n  --warning-fg:var(--amber-3);--warning-emphasis:var(--amber-4);--warning-muted:rgba(224,144,15,.42);--warning-subtle:rgba(224,144,15,.14);\n  --verified-fg:var(--violet-3);--verified-emphasis:var(--violet-5);--verified-muted:rgba(132,96,232,.42);--verified-subtle:rgba(132,96,232,.16);\n\n  --sev-p0-fg:var(--danger-fg); --sev-p0-subtle:var(--danger-subtle); --sev-p0-muted:var(--danger-muted);\n  --sev-p1-fg:var(--warning-fg);--sev-p1-subtle:var(--warning-subtle);--sev-p1-muted:var(--warning-muted);\n  --sev-p2-fg:var(--info-fg);   --sev-p2-subtle:var(--info-subtle);   --sev-p2-muted:var(--info-muted);\n\n  --focus-ring:var(--green-3);\n}\n\n:root{\n  /* Space Grotesk — display / brand voice; Hanken Grotesk — UI & body; JetBrains Mono — evidence.\n     Latin faces are self-hosted (see styles/fonts.css). CJK resolves to the reader's\n     system face: Noto Sans SC is not shipped as a webfont — the npm package is 71.6 MB,\n     which is untenable for a repository whose product claim is auditable local-first. */\n  --font-display:'Space Grotesk','Hanken Grotesk',system-ui,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','Noto Sans CJK SC','Noto Sans SC',sans-serif;\n  --font-sans:'Hanken Grotesk',system-ui,-apple-system,'Segoe UI','PingFang SC','Hiragino Sans GB','Microsoft YaHei','Noto Sans CJK SC','Noto Sans SC',sans-serif;\n  --font-mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;\n\n  --text-display-1:clamp(46px,5.4vw,76px);\n  --text-display-2:clamp(32px,3.6vw,46px);\n  --text-h1:34px;\n  --text-h2:26px;\n  --text-h3:20px;\n  --text-h4:17px;\n  --text-body-lg:18px;\n  --text-body:16px;\n  --text-body-sm:15px;\n  --text-caption:13px;\n  --text-label:12px;\n  --text-micro:11px;\n\n  --leading-display:1.02;\n  --leading-heading:1.12;\n  --leading-body:1.6;\n  --leading-tight:1.3;\n\n  --tracking-display:-0.02em;\n  --tracking-tight:-0.01em;\n  --tracking-normal:0;\n  --tracking-label:0.08em;\n\n  --weight-regular:400;\n  --weight-medium:500;\n  --weight-semibold:600;\n  --weight-bold:700;\n  --weight-heavy:800;\n}\n\n:root{\n  --space-px:1px;\n  --space-1:4px;  --space-2:8px;  --space-3:12px; --space-4:16px;\n  --space-5:20px; --space-6:24px; --space-7:32px; --space-8:40px;\n  --space-9:48px; --space-10:56px;--space-11:64px;--space-12:80px;\n  --space-13:96px;--space-14:120px;\n\n  --container-max:1200px;\n  --container-narrow:760px;\n  --gutter:24px;\n  --section-pad-x:clamp(20px,5vw,64px);\n  --section-pad-y:clamp(56px,8vw,96px);\n}\n\n:root{\n  --radius-sm:6px;\n  --radius-control:10px;\n  --radius-card:12px;\n  --radius-panel:16px;\n  --radius-lg:20px;\n  --radius-pill:999px;\n\n  --border-w:1px;\n\n  /* elevation — soft, cool-tinted; overridden for dark below */\n  --shadow-resting:0 1px 2px rgba(15,30,50,.06),0 1px 3px rgba(15,30,50,.08);\n  --shadow-raised:0 6px 16px rgba(15,30,50,.10);\n  --shadow-overlay:0 16px 48px rgba(15,30,50,.18);\n  --shadow-panel:0 28px 90px rgba(5,13,24,.28);\n  /* Tinted from the fill the primary button actually uses (--accent-emphasis-strong,\n     green-7), not from green-5. A glow 2.5x brighter than the surface it sits under does\n     not read as bloom, it reads as a halo in the wrong colour. */\n  --shadow-cta:0 10px 24px rgba(3,110,62,.34),inset 0 1px 0 rgba(255,255,255,.16);\n\n  --duration-fast:.12s; /* @kind other */\n  --duration-base:.18s; /* @kind other */\n  --ease-out:cubic-bezier(.16,1,.3,1); /* @kind other */\n  --ease-standard:cubic-bezier(.4,0,.2,1); /* @kind other */\n\n  /* console instrument texture */\n  --grid-line:rgba(148,163,184,.05); /* @kind other */\n  --grid-size:56px;\n  --gradient-ambient:radial-gradient(ellipse 900px 500px at 70% -10%,rgba(6,168,92,.16),transparent 60%); /* @kind other */\n}\n[data-theme=\"dark\"]{\n  --shadow-resting:0 1px 2px rgba(0,0,0,.4);\n  --shadow-raised:0 8px 24px rgba(0,0,0,.45);\n  --shadow-overlay:0 20px 60px rgba(0,0,0,.6);\n  --shadow-panel:0 30px 90px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.04);\n  --shadow-cta:0 12px 28px rgba(3,110,62,.42),inset 0 1px 0 rgba(255,255,255,.14);\n}\n\n/* Minimal base — sets document typography & link colors from tokens.\n   Consumers linking styles.css get sensible defaults; components never depend on it. */\n*,*::before,*::after{box-sizing:border-box}\nbody{margin:0;font-family:var(--font-sans);font-size:var(--text-body);line-height:var(--leading-body);color:var(--fg-default);background:var(--canvas-default);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}\na{color:var(--link-fg);text-decoration:none}\na:hover{color:var(--link-hover-fg)}\n::selection{background:var(--accent-muted);color:var(--fg-on-emphasis)}";
